namespace Chargehand.Modules.Pool.Api;

/// <summary>Where an item is in its life: waiting, held by a live worker, or finished.</summary>
public enum PoolStatus
{
    Queued,
    Claimed,
    Done,
}

/// <summary>What one worker takes as a batch: a repository and a short area label the producer chose (ADR 0099).</summary>
public sealed record PoolScope(string Repository, string Area);

/// <summary>One unit of work in the pool.</summary>
/// <param name="Key">Opaque, generated by the store.</param>
/// <param name="Source">Who enqueued it: <c>enqueue</c> for the tool, later <c>intake</c>.</param>
/// <param name="Repository"><c>owner/name</c>.</param>
/// <param name="Area">The scope label within the repository.</param>
/// <param name="Priority">0 is normal; higher starts first.</param>
/// <param name="PullRequest">The pull request this item works on, when it is one; such scopes start first.</param>
/// <param name="Worker">The live worker holding a claimed item.</param>
/// <param name="Reason">For a queued item, the check (or <c>starter</c>, <c>lost</c>, <c>ceiling</c>) that last held or released it.</param>
public sealed record PoolItem(
    string Key,
    string Source,
    string Repository,
    string Area,
    string Title,
    string Body,
    int Priority,
    int? PullRequest,
    DateTimeOffset EnqueuedAt,
    PoolStatus Status,
    string? Worker,
    string? Reason,
    DateTimeOffset? ClaimedAt,
    DateTimeOffset? DoneAt)
{
    public PoolScope Scope => new(Repository, Area);
}

/// <summary>What a worker leaves for its successor when the ceiling ends it (ADR 0099).</summary>
public sealed record ResumeCard(string Done, string Left, string Stopped, string? Worker = null, DateTimeOffset? WrittenAt = null);

/// <summary>A live or ended worker: one per scope at a time.</summary>
public sealed record PoolWorker(string Id, PoolScope Scope, long Tokens, DateTimeOffset StartedAt, DateTimeOffset? ReleasedAt, string? Reason);

/// <summary>A refusal with a stable code; the message never quotes the refused value.</summary>
public sealed record PoolRefusal(int Status, string Code, string Message);

/// <summary>The written item and where it sits among its scope's queued items (1 = next).</summary>
public sealed record Enqueued(PoolItem Item, int Position);
